      "why": "What is stable: consumer vs implementer, named arguments, additions, enums, formats, generator and comparison",
      "required": true
    },
    {
60→      "ref": "knowledge/contracts#rules",
      "why": "Conventions: attributes, positional Implement calls, generics are part of the contract",
      "required": true
    },
    {
      "ref": "knowledge/contracts#markers",
      "why": "Api/Spi/SpiKind and @internal semantics",
      "required": true
    },
    {
