      "id": "V4",
      "cmd": "php -d memory_limit=1G vendor/bin/pest tests/Arch --fail-on-skipped",
190→      "expect": "exit 0",
      "kind": "acceptance"
    },
    {
      "id": "V5",
      "cmd": "composer analyse && composer lint:check && composer refactor:check && composer api:check",
      "expect": "exit 0",
      "kind": "acceptance"
    }
  ],
