 */
function compatOnType(string $fqcn, callable $mutate): Closure
{
    return static function (array $manifest) use ($fqcn, $mutate): array {
        $found = false;

        foreach ($manifest['classes'] as $index => $type) {
            if ($type['name'] === $fqcn) {
                $manifest['classes'][$index] = $mutate($type);
                $found = true;
